  ('sachatuatn', 'Sachatuatn', 'die', '', '', 'Wiener Küche & Gaumenfreuden', 'Sachertorte', '[{"kategorie": "wörtlich", "text": "\"Sachertorte\" (berühmte, traditionelle österreichische Schokoladentorte aus zwei Lagen saftigem Schokoladenbiskuit, gefüllt mit Marillenmarmelade (Aprikosenmarmelade) und überzogen mit einer glänzenden, festen Schokoladenglasur. Sie wird klassischerweise mit ungesüßtem Schlagobers (Schlagsahne) serviert)"}, {"kategorie": "allg.", "text": "\"Original Sacher Torte\" (erfunden 1832 in Wien von Franz Sacher, damals 16-jähriger Lehrling im Dienst des Fürsten Metternich; berühmt geworden durch das Hotel Sacher, gegründet von Sachers Sohn Eduard; der Name „Original Sacher-Torte“ ist heute eine geschützte Marke des Hotel Sacher)"}, {"kategorie": "", "text": "Demel’s Sachertorte“ (andere, aber ebenfalls traditionsreiche Variante, benannt nach der berühmten K. u. K. Hofzuckerbäckerei Demel in Wien)"}]'::jsonb, 'A Sachatuatn oone Schlogoowas is wiara Schoklaad oone Kakau!'),
  ('schlogoowasgupf', 'Schlogoowasgupf', 'der', '', '', 'Wiener Kaffeehaus-ABC', 'Schlagobersgupf', '[{"kategorie": "wörtlich", "text": "\"Sahnehäubchen\" (Determinativkompositum aus [[Schlagobers]]=\"Schlagsahne\" und [[Gupf]]=\"Häubchen\")"}, {"kategorie": "allg.", "text": "Sahnetupfer, Cremehäubchen, Sahnekrönchen, [[Schlogoowashauwal]]"}, {"kategorie": "fig.", "text": "\"Sahnehäubchen\", \"das Extra obendrauf\", \"das Tüpfelchen auf dem i\", \"die Kirsche auf der Torte\", [[das Zuckerl obendrauf]]"}]'::jsonb, 'Da Kaffee woa schwoaz wia mei Söö - owa min Schlogoowasgupf obndrauf lächld di da Moagn daunn doch wiida saunft au!'),
  ('guakn', 'Guakn', 'die', '', '', 'Grundwortschatz Wienerisch', 'Gurken', '[{"kategorie": "wörtlich", "text": "\"Gurke\" (vom tschechischen \"okurka\"=\"Gurke\")"}, {"kategorie": "bot.", "text": "Salatgurke, Gemüsegurke, \"grüne Gurke\", (botanischer Name): \"Cucumis sativus\""}, {"kategorie": "scherzhaft für", "text": "\"große, hässliche Nase\", \"Zinken\", \"Riechkolben\", [[Heampa]], [[Ruabm]], [[Pfrnak]], [[Riassl]], [[Umuakn]]"}, {"kategorie": "in Bezug auf das weibliche Geschlecht", "text": "\"dumme Gans\", \"Ziege\", \"Dumpfbacke\", \"Hohlbirne\", [[Traumpä]], [[Trulla]]"}, {"kategorie": "scherzhaft für", "text": "\"altersschwaches Auto, Motorrad, Moped\", \"Kiste\", \"Karre\", \"Klapperkiste\", \"Rostlaube\", [[Kraxn]]"}, {"kategorie": "scherzhaft für", "text": "\"altes, funktionsschwaches Handy, Mobiltelefon, Smartphone\", \"Handy-Fossil\", \"Uralt-Handy\""}, {"kategorie": "scherzhaft für", "text": "Phallus, männliches Glied, Schwanz, [[Beidl]], [[Nudel]], [[Hugo]], [[Fruchtwurzen]], [[Brunzwimmerl]], [[Zumpferl]]"}, {"kategorie": "Gaunersprache", "text": "Gummiknüppel, Polizeiknüppel, [[Gummiwuaschd]], [[Käun]], [[Bundeswuaschd]]"}]'::jsonb, 'Waunnsd beim Owakiiwara de Goschn aufreissd, host glei de Guakn im Gnack!'),
  ('guaknglaasln', 'Guaknglaasln', 'die', '', '', 'Grundwortschatz Wienerisch', 'Gurkenglaseln', '[{"kategorie": "wörtlich, Pluralform", "text": "\"Gurkengläser\" (Determinativkompositum aus \"Gurken\"=\"Gurkenscheiben\" [scherzhaft für] \"Augen\" und \"Gläser\"=\"Brille\")"}, {"kategorie": "scherzhaft für", "text": "\"dicke Hornbrille\", \"Nerd-Brille\", [[Schbekuliaeisn]], [[Scheanglproteesn]], [[Fru-Fru-Glasn]], [[Gloosbotzn]]"}]'::jsonb, 'Heast, Klaane, mit deine Guaknglaasln und dein schiifn Lochn schausd aus wia da weibliche Harry Potter!'),
  ('guaknhaundl', 'Guaknhaundl', 'der', '', '', 'Grundwortschatz Wienerisch', 'Gurkenhandel', '[{"kategorie": "wörtlich", "text": "\"Gurkenhandel\" (Determinativkompositum aus \"Gurken\"=\"Gewürzgurken\" und \"Handel\"=\"Einzelhandel\")"}, {"kategorie": "allg.", "text": "\"Kauf und Verkauf von sauren Gurken\", \"Einzelhandel mit Sauergemüse\", \"Gurkenstand\" (Bezug: Bis in die zweite Hälfte des 20. Jahrhunderts gab es in Wien kleine Verkaufsstände – sogenannte „Gurkenstandeln“ , an denen essigsauer eingelegte Gurkerln und anderes saures Gemüse angeboten wurden: Salzgurken, Pfefferoni, Mixed Pickles, Sauerkraut, Silberzwiebel etc. Diese Standeln waren keine Würstelstände, sondern eigene kleine Kioske – oft in Parks oder an Uferpromenaden, wie z. B. an der unteren Alten Donau)"}, {"kategorie": "fig.", "text": "\"Gurkenhandel\", \"ewiges Herumgefeilsche\", \"Pfennigfuchserei\", \"Geschachere\""}]'::jsonb, 'Aum Uufa da Oidn Donau hod friara da Guaknhaundl in klaane Hoizhittn so richtig floariad!'),
  ('guakngreidl', 'Guakngreidl', 'das', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Gurkenkräutl', '[{"kategorie": "wörtlich", "text": "\"Gurkenkraut\" (Determinativkompositum aus \"Gurke\"=\"Gewürzgurke\" und \"Kraut\"=\"Küchenkraut\")"}, {"kategorie": "allg.", "text": "Dille (ist eine gängige Zutat beim Einlegen von Gurken), Dillkraut, Dill (botanischer Name): \"Anethum graveolens\""}]'::jsonb, 'Wia soong ned ''Düü'', sondan ''Guakngreidl'', wäu damit traditionell Gwiazguakn eigleegd wean!'),
  ('guaknscheibm', 'Guaknscheibm', 'die', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Gurkenscheibe', '[{"kategorie": "wörtlich", "text": "\"Gurkenscheibe\" (Determinativkompositum aus \"Gurke\"=\"Salatgurke\" und \"Scheibe\"=\"rundes, flaches Stück\")"}, {"kategorie": "allg.", "text": "\"Salatgurkenscheibe\", \"Gurkenring\", \"fein geschnittenes Gurkenscheibchen\""}]'::jsonb, ''),
