  ('guakal', 'Guakal', 'das', '', '', 'Grundwortschatz Wienerisch', 'Gurkerl', '[{"kategorie": "wörtlich", "text": "\"kleine Gurke\" (Diminutivum von \"Gurke\" - vom tschechischen \"okurka\"=\"Gurke\")"}, {"kategorie": "Kulinarik", "text": "\"kleine Essiggurke im Glas\", \"Gewürzgurkerl\", \"saures Gurkerl\", \"Gurkerl in Essigsud\", \"Salzgurkerl\", [[Krokodüü]]"}, {"kategorie": "in Bezug auf das weibliche Geschlecht", "text": "\"naives, gutgläubiges, etwas weltfremdes Mädchen\", \"Kindskopf\", \"Unschuld vom Land\", [[Ganserl]]"}, {"kategorie": "sexuell, scherzhaft für", "text": "\"kleiner Penis\", \"Miniatur-Penis\", \"Schniedelwutz\", [[Zumpfal]], [[Blunzal]], [[Wuschal]], [[Zipfal]]"}, {"kategorie": "Fußballerjargon", "text": "\"Schuss durch die Beine\", \"Schuss durch die Hösenträger\", (\"Deutschland): \"Tunnelschuss\""}]'::jsonb, 'Sei Ego is grooss - sei Guakal eeha ned!'),
  ('mei', 'Mei!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Mei!', '[{"kategorie": "wörtlich", "text": "\"Mei!\" (Ausruf der Verwunderung, Ergriffenheit oder Betroffenheit)"}, {"kategorie": "", "text": "Meine Güte!  3. Mein Gott!  4. Na sowas!  5. Aber ja doch!  6. \"Tja, so ist es halt!\"  7. Was willst machen?  8. Was soll''s?"}]'::jsonb, ''),
  ('guakaln', 'guakaln', '', '', '', 'Echte Wiener Schmähperlen', 'gurkerln', '[{"kategorie": "wörtlich", "text": "\"die Gurke auswinden\" (von [[Gurke]]=\"Penis\")"}, {"kategorie": "allg.", "text": "urinieren, Wasser lassen, pinkeln, pischen, [[brunzn]], [[wieschln]], [[schiffn]], [[in]] Kaschbal schneizn, [[in]] Familienschdrumpf auswindn"}]'::jsonb, 'De Kiiwara haum an Droogntest mit mia gmochd -oiso hob I in eanan Plastikbecha guakald!'),
  ('umanaundguakn', 'umanaundguakn', '', '', '', 'Grundwortschatz Wienerisch', 'herumgurken', '[{"kategorie": "wörtlich", "text": "\"rumgurken\" (Kompositum aus dem abtrennbaren Präfix [[umanaund]]=\"herum\" und [[gurken]]=\"trödeln\")"}, {"kategorie": "allg.", "text": "rumtrödeln, umständlich agieren, herumtun, \"herumeiern\", \"vor sich hinwursteln\""}, {"kategorie": "mit dem Auto", "text": "\"sinnlos herumfahren\", \"rumtuckern\", \"herumkurven\", \"im Schneckentempo herumgurken\", \"ziel- und orientierungslos dahinschleichen\""}]'::jsonb, 'Wia san eewich in da Schdodt umanaundaguakd, wäu ma kan Parkplotz gfundn haum!'),
